import hashlib
import hmac


class SignatureError(Exception):
    pass


def _expected(secret, body, timestamp):
    return hmac.new(secret, f"{timestamp}.".encode("ascii") + body, hashlib.sha256).hexdigest()


def sign_webhook(secret, body, timestamp):
    return f"t={timestamp},v1={_expected(secret, body, timestamp)}"


def verify_webhook(header, body, secrets, now, tolerance=300):
    if not header:
        raise SignatureError("missing signature")
    stamps, signatures = [], []
    for item in header.split(","):
        name, eq, value = item.strip().partition("=")
        if not eq:
            continue
        if name == "t":
            stamps.append(value)
        elif name == "v1":
            signatures.append(value)
    if len(stamps) != 1 or not stamps[0].isdigit():
        raise SignatureError("bad timestamp")
    if not signatures:
        raise SignatureError("no v1 signature")
    timestamp = int(stamps[0])
    if abs(now - timestamp) > tolerance:
        raise SignatureError("timestamp out of range")
    for secret in secrets:
        expected = _expected(secret, body, timestamp)
        if any(hmac.compare_digest(expected, s) for s in signatures):
            return timestamp
    raise SignatureError("signature mismatch")

