import hashlib, hmac

BODY = b'{"id":"evt_1","type":"order.paid"}'
OLD, NEW = b"whsec_old", b"whsec_new"

def reason(header, body=BODY, secrets=(NEW,), now=1000, **kw):
    try:
        verify_webhook(header, body, list(secrets), now, **kw)
    except SignatureError as e:
        return str(e)
    return "ok"

@test("signing")
def _():
    expected = hmac.new(NEW, b"1000." + BODY, hashlib.sha256).hexdigest()
    check_eq(sign_webhook(NEW, BODY, 1000), f"t=1000,v1={expected}")

@test("a genuine delivery")
def _():
    check_eq(verify_webhook(sign_webhook(NEW, BODY, 1000), BODY, [NEW], 1000), 1000)
    check_eq(reason(sign_webhook(NEW, BODY, 1000)), "ok")

@test("rotation: several secrets, several signatures")
def _():
    check_eq(reason(sign_webhook(OLD, BODY, 1000), secrets=(NEW, OLD)), "ok")
    sig_old = sign_webhook(OLD, BODY, 1000).split(",")[1]
    sig_new = sign_webhook(NEW, BODY, 1000).split(",")[1]
    check_eq(reason(f"t=1000, {sig_old} ,{sig_new}"), "ok")
    check_eq(reason(f"t=1000,v0=abc,{sig_new}"), "ok")

@test("each kind of rejection")
def _():
    good = sign_webhook(NEW, BODY, 1000)
    check_eq(reason(None), "missing signature")
    check_eq(reason(""), "missing signature")
    check_eq(reason(good.replace("t=1000", "t=10a0")), "bad timestamp")
    check_eq(reason(good.split(",")[1]), "bad timestamp")
    check_eq(reason("t=1000,t=1000," + good.split(",")[1]), "bad timestamp")
    check_eq(reason("t=1000"), "no v1 signature")
    check_eq(reason(good, now=1301), "timestamp out of range")
    check_eq(reason(good, now=699), "timestamp out of range")
    check_eq(reason(good, now=1300), "ok")
    check_eq(reason(good, now=1060, tolerance=60), "ok")
    check_eq(reason(good, body=BODY + b" "), "signature mismatch")
    check_eq(reason(good, secrets=(OLD,)), "signature mismatch")
    check_eq(reason(good, secrets=()), "signature mismatch")

